import { injectable } from 'inversify';
import { IGenerateContractRepository } from '@src/domain/interfaces/loan_collateral/generate_contract';
import { GenerateContractResponse } from '@src/domain/entities/loan_collateral/generate_contract';
import { HttpService } from '@core/service';
import { BASE_URL_LOAN_API } from '@src/config';
import { GenerateContractPayload } from '@src/application/loan_collateral/queries/generate_contract/generate_contract_query';
import uuid from 'react-native-uuid';
import { commonService } from '@src/infrastructure/network/networkService';

@injectable()
export class GenerateContractRepository extends HttpService implements IGenerateContractRepository {
    constructor() {
        super({ baseURL: BASE_URL_LOAN_API });
    }
    async generateContract(query: GenerateContractPayload): Promise<GenerateContractResponse> {
        const request = query as unknown as GenerateContractPayload;
        const url = '/generateContract';
        const dataReq = {
            ...request,
            requestId: uuid.v4(),
        };

        const { data } = await this.post(url, dataReq, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-loan-collateral' }),
        });
        // console.log('\x1b[36m response generate contract', data);
        return data as GenerateContractResponse;
    }
}
