import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_LOAN_API } from '@src/config';
import { ClientInfo } from '@src/domain/entities/common/clientInfo';
import { GetClientInfoPayload } from '@src/application/common/get_client_info/get_client_info_payload';
import { LoanDemandResponse, RegisterLoanDemandPayload } from '@src/domain/entities/loan_register/loanDemand';
import { ILoanDemandRepository } from '@src/domain/interfaces/loan_register/loanDemand';
import { store } from '@src/lib/redux';
import { commonService } from '@src/infrastructure/network/networkService';

@injectable()
export class LoanDemandRepository
    extends HttpService
    implements ILoanDemandRepository {
    constructor() {
        super({ baseURL: BASE_URL_LOAN_API });
    }

    async registerLoanDemand<TParameter>(query: Query<TParameter>): Promise<LoanDemandResponse> {
        const request = query.query as unknown as RegisterLoanDemandPayload;
        const url = '/registerLoanDemand';
        const token = store.getState().product.token;
        const response = await this.post(url, request, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-loan-register' }),
        })
        console.log('\x1b[31m respose registerloandermand', response, request);
        return response.data as LoanDemandResponse;
    }
}
